{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "A close benzamidine-containing analogue with carboxylic acid and amide functionalities had absolute bioavailability not high enough for oral use in humans, directly supporting low F for the query's benzamidine/peptide-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Pentamidine, a bis-benzamidine drug, is reported to have poor oral bioavailability in humans; the query contains the same strongly basic benzamidine moiety, supporting low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DX-9065a, a factor Xa inhibitor with strong basic amidino groups and a carboxylic acid, had human oral bioavailability of only 2–3%, attributed to the amidine groups; this is highly relevant to the query's benzamidine and carboxylate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Perindopril, a peptide-like drug with a proline/cyclohexane scaffold and carboxylic acid, had oral bioavailability of 19 ± 7% in young healthy subjects, just below the 20% threshold; the query shares proline amide, cyclohexyl, and carboxylate features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Peramivir, containing a guanidine, cyclopentane, and carboxylic acid, had very low oral bioavailability (≤3%) in humans; the query's strongly basic amidine plus carboxylate and cyclohexyl groups predict similarly poor absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "L-arginine, a small guanidine amino acid, can reach about 68% oral bioavailability at 6 g in healthy humans, showing that a basic guanidine/amidine alone does not preclude high F; however, the query is much larger and more peptide-like, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have low oral bioavailability (<20%) because close analogues containing benzamidine/amidine, carboxylic acid, and peptide-like motifs consistently show very low human oral bioavailability (2–10%), and the few high-F comparators lack the query's strongly basic amidine and multiple amide H-bond donors.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself.",
    "Fed-state condition is not directly represented in the retrieved records; most bioavailability values are from fasted or unspecified conditions.",
    "The query's exact transporter and metabolic liabilities are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

